  { tag: tags.attributeName, color: '${fnColor}' },
  { tag: tags.labelName, color: '${fnColor}' },
  { tag: tags.comment, color: '${commentColor}', fontStyle: 'italic' },
  { tag: tags.self, color: '${kwColor}' },
  { tag: tags.typeName, color: '${typeColor}' },
